def verify():
    par = lambda a, b: a * b / (a + b)
    assert par(6, 3) == 2 and 12 * 2 / 6 == 4 and 9 * 3 / 9 == 3
    V = (2 + 10 / 2) / (1 / 2 + 1 / 2); assert V == 7          # 3단원 마디
    import numpy as np
    i1, i2 = np.linalg.solve([[3, -2], [-2, 4]], [10, 0]); assert abs(i1 - 5) < 1e-9
    vth, rth = 6, par(4, 4); assert rth == 2 and vth ** 2 / (4 * rth) == 4.5 and vth / rth == 3
    assert abs(0.5 * 10e-6 * 100 ** 2 - 0.05) < 1e-12 and abs(par(2, 3) - 1.2) < 1e-12
    assert abs(1e4 * 1e-4 - 1) < 1e-12 and round(100 * (1 - math.exp(-1))) == 63
    w0 = 1 / math.sqrt(1 * 0.25); assert w0 == 2 and abs(math.sqrt(w0 ** 2 - 1) - 1.732) < 1e-3 and 2 * 1 * w0 == 4
    assert round(377 / (2 * math.pi)) == 60 and abs(1 / (1000 * 100e-6) - 10) < 1e-9
    assert abs(math.sqrt(100 * 10 ** 2 - 800 ** 2 / 100) * 0 + 100 * 10 * 0.6 - 600) < 1e-9
    assert abs(math.sqrt(3) * 220 - 381.05) < 0.01 and abs(math.sqrt(3) * 380 * 10 - 6581.8) < 0.1 and abs(math.sqrt(3) * 10 - 17.32) < 0.01
    assert abs(1 / math.sqrt(10e-3 * 1e-6) - 1e4) < 1e-6 and abs(1e4 * 0.01 / 10 - 10) < 1e-9
    assert abs(1 / (2 * math.pi * 1e3 * 1e-6) - 159.15) < 0.01 and abs(20 * math.log10(1 / math.sqrt(2)) + 3.01) < 0.01
    assert 10 ** 2 * 8 == 800 and 2 / math.sqrt(16) == 0.5 and 220 / 5 == 44
    # 균형 3상 전류 합 = 0
    assert abs(sum(cmath.rect(1, k * 2 * math.pi / 3) for k in range(3))) < 1e-12


if __name__ == "__main__":
    verify()
    write_subject(SUBJECT, U)
